    // Scrambling is bad

    
        Dbl-clocked GigaDuna-minx
        Other forms\Dodecahedron\Face Turning\Bandaged\Dbl-clocked GigaDuna-minx
        virtual model by AndyKybik
        AndyKybik
        2024-11-01
        
    

    
        R := 0.7;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        D1 := (3 * Rsin + 1 * R2sin) / 4;
        D2 := (2 * Rsin + 2 * R2sin) / 4;

        procedure Prepare();
        begin
            Count := Length(S) div 3;
            for i := 0 to Count - 1 do begin
                ax[i] := StrToInt(copy(S, i * 3 + 1, 1));
                L[i] := StrToInt(copy(S, i * 3 + 2, 1));
                Sign := copy(S, i * 3 + 3, 1);
                if Sign = '-' then begin
                    FromL[i] := L[i] + 1;
                    ToL[i] := 20;
                end else if Sign = '+' then begin
                    FromL[i] := 0;
                    ToL[i] := L[i];
                end else begin
                    FromL[i] := 20;
                    ToL[i] := 20;
                end;
            end;
        end;
    

    
        
        
        
        
        
        
    

    
        

        
            
            
             Inc(i); 
        
        
             Prepare; 
            
            
        

        // "52-" means split axis = "5" From = "2+1" and hide lower or upper half depending on sign
        // these strings split very bandaged puzzle
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        

        
               
               
